using System.Security.Claims;
using System.Security.Cryptography;
using Microsoft.Data.SqlClient;
using Microsoft.AspNetCore.Identity;
namespace Aarohi;
public record HouseholdSelection(long HouseholdId);
public record InviteRequest(string Email,long RoleId);
public record AcceptInviteRequest(string Token,string Name,string Email,string Password,DateTime BirthDate);
public static class Invitations
{
 public static void MapInvitations(this WebApplication app){
 app.MapGet("/api/auth/households",async(ClaimsPrincipal u,Db db)=>{await using var c=await db.Open();var ids=await Db.Query(c,"SELECT HouseholdId FROM auth.UserHousehold WHERE UserId=@u",new(){["u"]=Db.User(u)});var homes=new List<Dictionary<string,object?>>();foreach(var item in ids){await Db.Exec(c,"EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=@h",new(){["h"]=item["HouseholdId"]});homes.AddRange(await Db.Query(c,"SELECT h.Id,h.Name FROM family.Household h JOIN family.Membership m ON m.HouseholdId=h.Id WHERE m.UserId=@u AND m.Status='Active' AND h.Status='Active'",new(){["u"]=Db.User(u)}));}return Results.Ok(homes);}).RequireAuthorization();
 app.MapPost("/api/auth/switch",async(HouseholdSelection r,ClaimsPrincipal u,Db db,TokenService tokens)=>{await using var c=await db.Open(r.HouseholdId);if(await Db.Scalar(c,"SELECT COUNT(*) FROM family.Membership WHERE UserId=@u AND Status='Active'",new(){["u"]=Db.User(u)})!=1)throw new ApiError(403,"Household access denied.");return Results.Ok(await AuthEndpoints.Session(c,Db.User(u),r.HouseholdId,tokens));}).RequireAuthorization();
 app.MapPost("/api/users/invitations",async(InviteRequest r,ClaimsPrincipal u,Db db)=>{await Resources.Guard(db,u,"users.manage");if(!System.Net.Mail.MailAddress.TryCreate(r.Email,out _)||r.Email.Length>254)throw new ApiError(400,"Enter a valid email address.");await using var c=await db.Open(Db.Household(u));if(await Db.Scalar(c,"SELECT COUNT(*) FROM auth.Role WHERE Id=@r AND IsActive=1",new(){["r"]=r.RoleId})==0)throw new ApiError(400,"Unknown role.");var code=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));await Db.Exec(c,"INSERT auth.HouseholdInvitation(HouseholdId,EmailNormalized,RoleId,TokenHash,ExpiresAt,CreatedByUserId) VALUES(@h,@e,@r,@hash,DATEADD(hour,24,SYSUTCDATETIME()),@u)",new(){["h"]=Db.Household(u),["e"]=r.Email.Trim().ToLowerInvariant(),["r"]=r.RoleId,["hash"]=SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(code)),["u"]=Db.User(u)});return Results.Ok(new{invitationCode=code,expiresInHours=24,message="Share this one-time code privately. No email was sent."});}).RequireAuthorization().RequireRateLimiting("auth");
 app.MapPost("/api/auth/accept-invite",async(AcceptInviteRequest r,Db db)=>{if(r.Token.Length!=64||string.IsNullOrWhiteSpace(r.Name)||r.Name.Length>120||r.Password.Length<12||r.Password.Length>128||r.BirthDate>DateTime.UtcNow.AddYears(-18)||r.BirthDate<DateTime.UtcNow.AddYears(-120))throw new ApiError(400,"Check your invitation, name, adult birth date and password (12–128 characters).");await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var invitations=await Db.Query(c,"SELECT HouseholdId,RoleId,Id FROM auth.HouseholdInvitation WITH(UPDLOCK,HOLDLOCK) WHERE TokenHash=@hash AND EmailNormalized=@e AND ConsumedAt IS NULL AND ExpiresAt>SYSUTCDATETIME()",new(){["hash"]=SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(r.Token)),["e"]=r.Email.Trim().ToLowerInvariant()},tx);if(invitations.Count!=1)throw new ApiError(400,"Invitation is invalid or expired.");var invite=invitations[0];long hid=Convert.ToInt64(invite["HouseholdId"]);await Db.Exec(c,"EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=@h",new(){["h"]=hid},tx);var existing=await Db.Query(c,"SELECT u.Id,u.Status,c.PasswordHash FROM auth.UserAccount u JOIN auth.LocalCredential c ON c.UserId=u.Id WHERE u.EmailNormalized=@e",new(){["e"]=r.Email.Trim().ToLowerInvariant()},tx);var hasher=new PasswordHasher<string>();long uid;
 if(existing.Count>0){if((string?)existing[0]["Status"]!="Active"||hasher.VerifyHashedPassword(r.Email,(string)existing[0]["PasswordHash"]!,r.Password)==PasswordVerificationResult.Failed)throw new ApiError(401,"Use your existing account password.");uid=Convert.ToInt64(existing[0]["Id"]);}else{uid=await Db.Scalar(c,"INSERT auth.UserAccount(DisplayName,EmailNormalized,Status) OUTPUT inserted.Id VALUES(@n,@e,'Active')",new(){["n"]=r.Name,["e"]=r.Email.Trim().ToLowerInvariant()},tx);await Db.Exec(c,"INSERT auth.LocalCredential(UserId,PasswordHash) VALUES(@u,@p)",new(){["u"]=uid,["p"]=hasher.HashPassword(r.Email,r.Password)},tx);}
 await Db.Exec(c,"INSERT family.Membership(HouseholdId,UserId,RoleId) VALUES(@h,@u,@r); INSERT auth.UserHousehold VALUES(@u,@h); INSERT family.Member(HouseholdId,Name,BirthDate,Relationship,UserId) VALUES(@h,@n,@birth,'Other',@u); UPDATE auth.HouseholdInvitation SET ConsumedAt=SYSUTCDATETIME() WHERE Id=@i",new(){["h"]=hid,["u"]=uid,["r"]=invite["RoleId"],["n"]=r.Name,["birth"]=r.BirthDate.Date,["i"]=invite["Id"]},tx);await tx.CommitAsync();return Results.Ok(new{message="Invitation accepted. Sign in to continue."});
 }).RequireRateLimiting("auth");
 }
}
